
/* 猫在呢 · Awoo Here | Mobile-first, offline-first interactive MVP. No external dependencies. */
(() => {
'use strict';
const KEY='awoo_here_mvp_v1';
const D={cat:'data:image/svg+xml;base64,',nap:'data:image/svg+xml;base64,',slipper:'data:image/svg+xml;base64,'};
const seed=()=>({version:1,cats:[{id:'cat-01',name:'猫猫一号',breed:'银灰长毛虎斑',birthday:'',arrival:'',sex:'',neutered:'',note:'',photo:'',createdAt:new Date().toISOString()}],selected:'cat-01',posts:[{id:'post-demo-1',catId:'cat-01',text:'小小一只，已经很会卖萌了。\n在这里收藏我们的日常 ♡',photos:[D.cat,D.slipper],tags:['小猫营业','好可爱'],createdAt:new Date().toISOString(),demo:true,liked:false},{id:'post-demo-2',catId:'cat-01',text:'猫咪的睡觉姿势，也是一门艺术。',photos:[D.nap],tags:['睡觉中'],createdAt:new Date(Date.now()-86400000).toISOString(),demo:true,liked:false}],health:[],chats:[]});
let state;try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):seed();if(!state.cats?.length||!Array.isArray(state.posts)||!Array.isArray(state.health))throw Error('data damaged')}catch{state=seed()}
// Keep older user-created entries while repairing demo-only legacy image URLs.
const legacyDrawings={'assets/photos/photo-meow.webp':D.cat,'assets/photos/photo-sleep.webp':D.nap,'assets/photos/photo-slipper.webp':D.slipper};
// Migrate ONLY the retired, identifiable demo drawing; user photos are never touched.
function retiredDemoArt(src){
 if(typeof src!=='string')return false;
 if(src.startsWith('assets/illustrations/cat-moment-'))return true;
 if(!src.startsWith('data:image/svg+xml;base64,'))return false;
 try {const markup=atob(src.slice(src.indexOf(',')+1));return markup.includes('<radialGradient id="fur">') && markup.includes('viewBox="0 0 520 430"');} catch {return false;}
}
let artMigration=false;
for(const c of state.cats){
 if(retiredDemoArt(c.photo)||legacyDrawings[c.photo]){c.photo='';artMigration=true;}
}
for(const post of state.posts){
 if(post.demo){
  const old=post.photos||[];
  const converted=old.map((src,i)=>retiredDemoArt(src)||legacyDrawings[src]?(post.id==='post-demo-2'?D.nap:(i===0?D.cat:D.slipper)):src);
  if(converted.some((item,i)=>item!==old[i])){post.photos=converted;artMigration=true;}
 }
}
// v0.6: previous built-in pixel/small vector portraits are NOT real pet photos.
function isBuiltInPortrait(src){
 if(typeof src!=='string'||!src)return false;
 if(src===D.cat||src.startsWith('assets/illustrations/')||src.startsWith('assets/photos/'))return true;
 if(src.startsWith('data:image/svg+xml'))return true;
 if(src.startsWith('data:image/png;base64,')){
  try {const bytes=atob(src.slice('data:image/png;base64,'.length, 'data:image/png;base64,'.length+42));
   if(bytes.slice(1,4)==='PNG'){const u=i=>bytes.charCodeAt(i);const w=((u(16)*16777216)+(u(17)*65536)+(u(18)*256)+u(19));const h=((u(20)*16777216)+(u(21)*65536)+(u(22)*256)+u(23));return w<=160&&h<=160;}
  }catch{}
 }
 return false;
}
for(const c of state.cats){if(isBuiltInPortrait(c.photo)){c.photo='';artMigration=true;}}
if(artMigration){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}

let ui={tab:'home',modal:'',healthTab:'overview',feedFilter:'all',draftTags:[],draftPhotos:[],draftText:'',petPose:'sit',petLine:'今天也在这里等你呀 ♡',catFormMode:'add',activeRecordType:'weight',working:false};
const $$=id=>document.getElementById(id);
const N=Date.now;
function uid(prefix='id'){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}
function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}

function hasRealPhoto(c){return !!(c&&typeof c.photo==='string'&&c.photo&&!isBuiltInPortrait(c.photo));}
function photoAvatar(c,size='small',editable=false){
 const real=hasRealPhoto(c),tag=editable?'button':'span';
 const attrs=editable?`type="button" data-action="upload-avatar" data-cat-id="${esc(c.id)}" aria-label="上传或更换 ${esc(c.name)} 的真实照片"`:'';
 return `<${tag} class="pet-photo-avatar pet-photo-${size} ${real?'has-photo':'needs-photo'}" ${attrs}>
 ${real?`<img src="${esc(c.photo)}" alt="${esc(c.name)}的真实照片"/>`:`<span class="photo-camera-icon">${icon('camera','sm')}</span>`}
 ${editable?`<span class="pet-photo-edit" aria-hidden="true">${icon('plus','sm')}</span>`:''}</${tag}>`;
}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('存储空间不足，请导出备份并减少大尺寸照片');return false}}
function cat(){return state.cats.find(c=>c.id===state.selected)||state.cats[0]}
function prettyDate(d){return new Date(d).toLocaleDateString('zh-CN',{month:'long',day:'numeric'})}
function dateString(d){return new Date(d).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'})}
function todayISO(){const d=new Date(),offset=d.getTimezoneOffset();return new Date(d.getTime()-offset*60000).toISOString().slice(0,10)}
function icon(name,cls=''){let shape={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',chat:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8A8.5 8.5 0 0 1 12.5 3h0a8.5 8.5 0 0 1 8.5 8.5z"/>',plus:'<path d="M12 5v14M5 12h14"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z"/>',pulse:'<path d="M3 12h4l3-7 4 14 3-7h4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',down:'<path d="m6 9 6 6 6-6"/>',right:'<path d="m9 18 6-6-6-6"/>',back:'<path d="m15 18-6-6 6-6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',check:'<path d="m4 12 5 5L20 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 10h18"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v13H3z"/><circle cx="12" cy="13" r="4"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 15-5-5L5 21"/>',send:'<path d="M22 2 11 13M22 2l-7 20-4-9-9-4z"/>',edit:'<path d="m14 5 5 5M4 20l4-1 12-12a2 2 0 0 0-4-4L4 15z"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5zm0 0A2.5 2.5 0 0 0 6.5 22H20"/>',weight:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M9 9h6M12 9l2 3"/>',medical:'<rect x="4" y="4" width="16" height="18" rx="2"/><path d="M9 3h6M12 9v8M8 13h8"/>',spark:'<path d="m12 2 2 7 7 3-7 2-2 7-3-7-6-2 6-3z"/>',trash:'<path d="M4 7h16M8 7V4h8v3M6 7l1 14h10l1-14M10 11v6M14 11v6"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.7 2.9-1.8-.7a8 8 0 0 1-1.9 1.1l-.3 2h-3.4l-.3-2a8 8 0 0 1-1.9-1.1l-1.8.7-1.7-2.9L7.5 15a9 9 0 0 1 0-2l-1.4-1.2 1.7-2.9 1.8.7a8 8 0 0 1 1.9-1.1l.3-2h3.4l.3 2a8 8 0 0 1 1.9 1.1l1.8-.7 1.7 2.9-1.4 1.2a9 9 0 0 1 0 2z"/>',refresh:'<path d="M20 11A8 8 0 0 0 6 6L3 9V3M4 13a8 8 0 0 0 14 5l3-3v6"/>',paw:'<circle cx="7" cy="6" r="1"/><circle cx="12" cy="4" r="1"/><circle cx="17" cy="6" r="1"/><path d="M6 15c2-2 2-5 6-5s4 3 6 5a4 4 0 0 1-4 6l-2-1-2 1a4 4 0 0 1-4-6z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2m-17-7 1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>'}[name]||'';return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${shape}</svg>`}
function topbar(name=''){return `<header class="topbar"><div class="brand-lockup"><img class="logo" src="data:image/svg+xml;base64," alt=""/><div><div class="brand-cn">${name||'猫在呢'}</div>${name?'':`<div class="brand-en">A W O O &nbsp; H E R E</div>`}</div></div><div class="top-actions"><button class="icon-button" data-action="settings" aria-label="设置">${icon('settings')}</button><button class="icon-button" data-action="cats" aria-label="切换或新增猫咪">${icon('paw')}</button></div></header>`}
/* Awoo Here · custom illustrated bottom dock */
function navGlyph(name){
 const frame=(inside)=>`<svg class="nav-art" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${inside}</svg>`;
 const outline='stroke="#4a5549" stroke-width="1.55" stroke-linejoin="round" stroke-linecap="round"';
 switch(name){
  case 'home':return frame(`<ellipse cx="25" cy="42.5" rx="21" ry="3.5" fill="#e9e5dc"/>
   <path d="M10 21 24 7l14 14v17q0 2-2 2H12q-2 0-2-2Z" fill="#f5d9bd" ${outline}/>
   <path d="M8 22 24 6l16 16-2.8 3.1L24 12 10.8 25Z" fill="#ba806a" stroke="#8f6655" stroke-width="1.5"/>
   <path d="M15.2 22h6.7v7h-6.7zm15 0h6.7v7h-6.7Z" fill="#e6f1e4" stroke="#72947c" stroke-width="1.4"/>
   <path d="M20.4 39V29h8v10Z" fill="#9b795f" stroke="#78665a" stroke-width="1.1"/>
   <path d="M5 35q4-8 9-4M39 34q-1-7 5-7" stroke="#7d9d7f" stroke-width="1.8"/>
   <ellipse cx="10" cy="31" rx="4" ry="2.4" transform="rotate(30 10 31)" fill="#98b392"/>
   <ellipse cx="42" cy="26" rx="4" ry="2.1" transform="rotate(-25 42 26)" fill="#9eb89e"/>
   <path d="M28 15q1-5 6-5" stroke="#d9aa85" stroke-width="1.5"/>`);
  case 'feed':return frame(`<g transform="rotate(-10 24 25)"><rect x="11" y="12" width="30" height="31" rx="3" fill="#e4d0ba" stroke="#bca591" stroke-width="1.7"/>
   <rect x="5" y="6" width="30" height="32" rx="3" fill="#fffdf7" stroke="#897b70" stroke-width="1.5"/>
   <rect x="9" y="10" width="22" height="20" rx="1.7" fill="#dfeae1"/>
   <path d="M12 23q-3-6 2-10l4 3 4-3q5-2 8 5l-3 7q-9 7-15-2Z" fill="#c6c6c0" stroke="#747875" stroke-width=".9"/>
   <path d="m13 16 1-8 7 7m6 0 3-7 1 12" fill="#bebbb7" stroke="#727470" stroke-width="1"/>
   <path d="M17 22q2-2 4 0m4 0q2-2 3 0" stroke="#3e504b" stroke-width="1.5" stroke-linecap="round"/>
   <path d="m21 25 2 1 2-1" stroke="#9e7470" stroke-width="1.4"/>
   <path d="M12 34h16" stroke="#b6c8b0" stroke-width="1.5"/></g>
   <path d="m37 4 1.5 4 4 1.5-4 1.5-1.5 4-1.5-4-4-1.5 4-1.5Z" fill="#e7b69b"/>`);
  case 'health':return frame(`<g transform="rotate(-7 24 24)"><path d="M13 6h23q4 0 4 4v31H13q-5 0-5-5V12q0-6 5-6" fill="#8ca68f" ${outline}/>
   <path d="M14 9h19q3 0 3 3v25H14q-3 0-3-3V12q0-3 3-3" fill="#fef9ed" stroke="#d6d2c8" stroke-width="1.2"/>
   <path d="M16 9v28" stroke="#b8c6b0" stroke-width="2"/>
   <path d="M27 17c-3-5-10 0-5 6l6 6 6-6c5-6-2-11-7-6Z" fill="#e4a7a1" stroke="#aa7874" stroke-width="1.4"/>
   <path d="M27 19v7m-3.5-3.5h7" stroke="#fff7ee" stroke-width="2" stroke-linecap="round"/></g>
   <path d="m6 6 2-3 1 4 4 2-4 1-2 4-1-4-4-1Z" fill="#eac49b"/>`);
  case 'ai':return frame(`<ellipse cx="24" cy="40" rx="16" ry="4" fill="#e5e5d6"/>
   <path d="M7 26q-3-6 1-10l8-4 5 6 10-1 5-5 7 4q3 8-1 13-2 12-18 12-19 0-17-15Z" fill="#adb1aa" stroke="#717976" stroke-width="1.6"/>
   <path d="M9 23 11 8l10 10M31 18l8-11 1 17" fill="#bdbcb8" stroke="#777b75" stroke-width="1.7"/>
   <path d="M12 14l1-4 5 7m15 0 5-7-1 10" fill="#d7b1ae"/>
   <path d="M17 21q-2 8-2 11m13-11q2 6 2 12M24 18q1 8-1 12" stroke="#676c70" stroke-width="3.2" opacity=".48" stroke-linecap="round"/>
   <path d="M13 32q4-4 8 0m8 0q4-4 8 0" stroke="#495854" stroke-width="2" stroke-linecap="round"/>
   <path d="m23 35 2 1 2-1" stroke="#b08d83" stroke-width="1.4"/>
   <path d="M22 38q3 3 5 0M18 36l-9-2m9 4-8 2m19-4 9-2m-9 4 8 2" stroke="#6a716e" stroke-width="1" stroke-linecap="round"/>
   <path d="m41 5 1.2 4 4 1.3-4 1.1-1.2 4-1.2-4-4-1.1 4-1.3Z" fill="#e0bda1"/>`);
 }
 return frame('');
}

function tabbar(){
  const tabs=[['home','猫猫窝'],['feed','喵喵圈'],['compose','嗷呜一下'],['health','健康'],['ai','懂喵君']];
  $$('tabbar').innerHTML=tabs.map(([id,label])=>id==='compose'
    ? `<div class="tab-center-wrap"><button class="tab-center" data-action="compose" title="嗷呜一下" aria-label="嗷呜一下，发布猫咪动态"><svg class="nav-add" viewBox="0 0 56 56" aria-hidden="true"><path d="M28 4.3c6.2 0 7.8 5.7 12.2 7.5 4.2 1.8 10.4.8 11.7 6 1.3 5.2-3.5 8.1-3.1 12.8.4 4.7 3.8 9.7-.9 13.2-4.7 3.5-10 0-14.4 2.5-4.4 2.6-6.7 7.1-12 5-5.2-2-5.4-7.6-10-10-4.7-2.4-10.9.4-13.3-4.6-2.5-5.1 2.3-9.3 2.6-14.2.3-5-4.5-8.4-1-12.4 3.4-4 8.6-1.8 12.5-4.4C19.2 8.6 22.1 4.3 28 4.3Z" fill="#5F7B69"/><path d="M27.8 19v18M18.8 28h18" stroke="#FFFDF8" stroke-width="3.3" stroke-linecap="round"/><path d="m39 10 2-4M45 14l4-2" stroke="#D8AC95" stroke-width="2.1" stroke-linecap="round"/></svg></button><span class="tab-center-label">${label}</span></div>`
    : `<button class="tab ${ui.tab===id?'is-active':''}" data-tab="${id}" aria-label="${label}" aria-current="${ui.tab===id?'page':'false'}"><span class="tab-figure">${navGlyph(id)}</span><span class="tab-label">${label}</span></button>`).join('');
}
function render(scrollTop=false){stopRoomLife();let oldScroll=$$('app').scrollTop;$$('app').innerHTML=({home:home,feed:feed,health:health,ai:chatView}[ui.tab]||home)();tabbar();if(scrollTop)$$('app').scrollTop=0;else $$('app').scrollTop=oldScroll;if(ui.tab==='ai')$$('app').scrollTop=0;if(ui.tab==='home')startRoomLife();}
const SPRITES={'loaf':'data:image/png;base64,','play':'data:image/png;base64,','sit':'data:image/png;base64,','sleep':'data:image/png;base64,','stretch':'data:image/png;base64,','walk-step1':'data:image/png;base64,','walk-step2':'data:image/png;base64,','walk':'data:image/png;base64,'};function sprite(p=ui.petPose){return SPRITES[p]||SPRITES.sit}
function home(){
 const c=cat(), posts=state.posts.filter(p=>p.catId===c.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
 return `<div class="v4-home">
   <div class="home-stage">
    <div class="stage-header"><button class="stage-brand" data-action="cats" aria-label="切换猫咪"><img src="data:image/svg+xml;base64," alt=""/><span><strong>猫在呢</strong><small>A W O O &nbsp; H E R E</small></span></button><button class="stage-alert" data-action="settings" aria-label="设置和提醒">${icon('bell')}</button></div>
    <div class="stage-intro"><span>下午好呀～</span><strong>猫猫今天也很乖呢。<i>♡</i></strong><small>${esc(c.name)}的小小世界 · 生活记录中</small></div>
    <div class="stage-room" id="homeRoom" aria-label="像素猫咪会自动走动、伸懒腰、趴下和睡觉"><div class="room-sunbeams"></div><div class="room-cat-actor" id="roomCatActor" aria-hidden="true"><span class="room-cat-shadow"></span><img id="roomCat" class="room-cat-pixel" src="${sprite('sit')}" alt="" draggable="false"/></div></div>
    <div class="stage-caption">${photoAvatar(c,'medium',true)}<span><strong>${esc(c.name)}的午后好呀 <span class="caption-heart">♡</span></strong><small id="roomMotion" role="status">正在小窝里休息…</small></span><button data-action="cats" aria-label="管理猫咪">${icon('right','sm')}</button></div>
   </div>
   <div class="home-body"><div class="shortcut-grid">
    <button class="feature-card" data-action="compose"><span class="feature-badge peach"><img src="data:image/svg+xml;base64," alt=""/></span><span><strong>嗷呜一下</strong><small>记录猫猫的小日常</small></span></button>
    <button class="feature-card" data-tab="health"><span class="feature-badge pink"><img src="data:image/svg+xml;base64," alt=""/></span><span><strong>健康小本本</strong><small>一切都帮你记着</small></span></button>
    <button class="feature-card" data-tab="ai"><span class="feature-badge sage"><img src="data:image/svg+xml;base64," alt=""/></span><span><strong>懂喵君</strong><small>聊聊最近的猫猫</small></span></button>
    <button class="feature-card" data-tab="feed"><span class="feature-badge blue"><img src="data:image/svg+xml;base64," alt=""/></span><span><strong>猫猫相册</strong><small>收藏可爱的瞬间</small></span></button>
   </div>
   <div class="v4-section-title"><strong>最近的小小日常</strong><button data-tab="feed">看看全部 ${icon('right','sm')}</button></div>
   ${posts.length?`<button class="memory-strip" data-tab="feed"><img src="${esc(posts[0].photos?.[0]||D.nap)}" alt=""/><span><small>${prettyDate(posts[0].createdAt)} · ${posts[0].demo?'示例动态':'新动态'}</small><strong>${esc((posts[0].text||'给猫猫留一句话').split('\n')[0].slice(0,26))}</strong><em>点开看看它的故事 ${icon('right','sm')}</em></span></button>`:`<button class="memory-empty" data-action="compose">这里还没有故事。发一条「嗷呜一下」吧。</button>`}
   <div class="home-signoff">AWOO HERE · 和小猫一起，慢慢生活</div>
  </div></div>`;
}
function feed(){
 const c=cat();let posts=state.posts.filter(p=>ui.feedFilter==='all'||(ui.feedFilter==='current'&&p.catId===c.id)||(ui.feedFilter==='mine'&&!p.demo)).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
 return `<div class="feed-screen"><header class="v4-pagehead"><div><h1>喵喵圈<span class="hand-heart">♡</span></h1><p>小猫的每一天，都值得收藏。</p></div><button class="head-control" data-action="cats" aria-label="切换猫咪">${icon('paw')}</button></header>
 <div class="feed-filters">${[['all','推荐'],['current','我的猫'],['mine','我的动态']].map(([id,name])=>`<button class="${ui.feedFilter===id?'active':''}" data-filter="${id}">${name}</button>`).join('')}</div>
 <section class="v4-feed">${posts.length?posts.map(postHTML).join(''):`<div class="v4-empty"><img src="${sprite('sleep')}" alt=""/><h2>还没有新的猫咪故事</h2><p>想记录的时候，再来分享就好。</p><button data-action="compose">嗷呜一下</button></div>`}</section></div>`;
}
function postHTML(p){
 const c=state.cats.find(x=>x.id===p.catId)||cat();let pics=p.photos||[];
 return `<article class="v4-post"><div class="post-author">${photoAvatar(c,'small',false)}<div><strong>${esc(c.name)}</strong><small>${prettyDate(p.createdAt)} · ${p.demo?'插画示例':'猫猫日常'}</small></div><button data-action="delete-post" data-id="${esc(p.id)}" title="删除这条动态" aria-label="删除动态">${icon('menu','sm')}</button></div>
 ${pics.length?`<div class="post-visual ${pics.length>1?'is-gallery':''}"><img src="${esc(pics[0])}" alt="猫咪生活记录" loading="lazy"/>${pics.length>1?`<span class="gallery-count">1 / ${pics.length}</span>`:''}</div>`:''}
 <div class="post-details"><strong>${esc(p.text?.split('\n')[0]||'今天的小猫又可爱了一点')}</strong>${p.text?.includes('\n')?`<p>${esc(p.text.split('\n').slice(1).join('\n'))}</p>`:''}${p.tags?.length?`<div class="v4-posttags">${p.tags.map(t=>`<span># ${esc(t)}</span>`).join('')}</div>`:''}
 <div class="post-footer"><button class="post-like ${p.liked?'liked':''}" data-action="like" data-id="${esc(p.id)}">${icon('heart','sm')} <span>${p.liked?'已收藏':'喜欢'}</span></button><span>${icon('chat','sm')} 留下美好</span><span class="post-day">${prettyDate(p.createdAt)}</span></div></div></article>`;
}
const types={weight:['体重记录','weight'],vaccine:['疫苗记录','medical'],deworm:['驱虫记录','spark'],visit:['就诊记录','medical'],note:['状态观察','book']};
function health(){
 const c=cat(),recs=state.health.filter(x=>x.catId===c.id).sort((a,b)=>new Date(b.date)-new Date(a.date)),weights=recs.filter(x=>x.type==='weight').sort((a,b)=>a.date.localeCompare(b.date)),w=weights.at(-1),pending=recs.filter(x=>x.nextDate&&x.nextDate>=todayISO()).sort((a,b)=>a.nextDate.localeCompare(b.nextDate));
 const points=weights.slice(-7);const age=c.birthday?ageLabel(c.birthday):'未填写';
 return `<div class="v4-health"><header class="v4-pagehead health-head"><div><h1>健康小本本</h1><p>好好照顾它，也好好陪伴它。</p></div><button class="head-control" data-action="add-health" aria-label="新增健康记录">${icon('plus')}</button></header>
 <div class="health-pet-card">
   ${photoAvatar(c,'large',true)}
   <button type="button" class="health-pet-info" data-action="cats" aria-label="切换猫咪"><span><strong>${esc(c.name)}</strong><small>${esc(c.breed||'猫咪档案')} · ${age}</small>${!hasRealPhoto(c)?'<small class="photo-upload-hint">点击左侧相机，上传真实头像</small>':''}</span><em>切换 ${icon('down','sm')}</em></button>
 </div>
 <div class="health-tabs">${[['overview','健康概览'],['history','健康记录'],['profile','猫咪资料']].map(([id,label])=>`<button data-healthtab="${id}" class="${ui.healthTab===id?'active':''}">${label}</button>`).join('')}</div>
 ${ui.healthTab==='profile'?profileView(c):ui.healthTab==='history'?historyView(recs):`<div class="health-overview">
  <div class="health-status"><div><small>今天的状态</small><strong>陪它好好生活 <span>♡</span></strong><p>没有设置每日打卡任务，<br>重要的事随时记就好。</p></div><div class="health-status-avatar">${hasRealPhoto(c)?`<img src="${esc(c.photo)}" alt="${esc(c.name)}的照片"/>`:`<button type="button" data-action="upload-avatar" data-cat-id="${esc(c.id)}" aria-label="上传猫咪真实照片">${icon('camera')}<small>添加照片</small></button>`}</div></div>
  <div class="health-metrics"><button data-action="record-type" data-type="weight"><small>最近体重</small><strong>${w?esc(w.value)+' <i>kg</i>':'—'}</strong><span>${w?esc(prettyDate(w.date)):'点此记录体重'} ${icon('right','sm')}</span></button><button data-healthtab="profile"><small>小猫年龄</small><strong>${age}</strong><span>完善猫咪档案 ${icon('right','sm')}</span></button></div>
  <section class="trend-panel"><div class="v4-section-title"><strong>体重趋势</strong><button data-action="record-type" data-type="weight">记体重 ${icon('plus','sm')}</button></div><div class="chart-filters"><span class="active">最近记录</span><span>${points.length} 条体重数据</span></div>${healthChart(points)}</section>
  <section class="reminder-panel"><div class="v4-section-title"><strong>待办提醒</strong><button data-action="add-health">查看 / 添加 ${icon('right','sm')}</button></div>${pending.length?pending.slice(0,3).map(x=>`<div class="reminder-item"><span class="reminder-icon">${icon('calendar')}</span><span><strong>${esc(x.title||types[x.type]?.[0]||'照护提醒')}</strong><small>${esc(x.nextDate)}</small></span><em>待完成</em></div>`).join(''):`<button class="reminder-empty" data-action="record-type" data-type="deworm"><span class="reminder-icon">${icon('calendar')}</span><span><strong>没有待办提醒</strong><small>驱虫、疫苗或复诊计划可以在这里记录</small></span>${icon('plus','sm')}</button>`}</section>
  <div class="health-tips">记录仅供日常整理，身体不适请咨询兽医。</div></div>`}
 </div>`;
}
function ageLabel(date){let x=new Date(date),now=new Date();if(!Number.isFinite(+x)||x>now)return '待确认';let months=(now.getFullYear()-x.getFullYear())*12+(now.getMonth()-x.getMonth())-(now.getDate()<x.getDate()?1:0);if(months<12)return `${Math.max(0,months)} 个月`;return `${Math.floor(months/12)} 岁${months%12?` ${months%12}个月`:''}`;}
function healthChart(weights){
 if(!weights.length)return `<div class="chart-empty"><svg viewBox="0 0 320 110" preserveAspectRatio="none" aria-hidden="true"><path d="M0 92H320M0 49H320M0 6H320" stroke="#e6eae0" stroke-dasharray="4 5"/><path d="M8 84Q64 78 102 57T218 49T313 20" stroke="#8ca391" stroke-width="3" stroke-dasharray="6 8" fill="none" opacity=".35"/></svg><span>记录体重后，这里会出现真实的变化曲线</span></div>`;
 const vals=weights.map(w=>Number(w.value));let min=Math.min(...vals),max=Math.max(...vals);if(min===max){min-=.2;max+=.2}const pts=vals.map((v,i)=>{let x=16+i*(286/Math.max(1,vals.length-1)),y=120-((v-min)/(max-min))*93;return [x,y]});const poly=pts.map(p=>p.join(',')).join(' ');return `<div class="chart-real"><svg viewBox="0 0 320 150" role="img" aria-label="根据已记录数据生成的体重折线图"><path d="M0 30H320M0 74H320M0 120H320" stroke="#e6eae0" stroke-dasharray="4 5"/><polyline points="${poly}" fill="none" stroke="#64826e" stroke-linejoin="round" stroke-width="3"/>${pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4.5" fill="#fff" stroke="#64826e" stroke-width="2.5"/>`).join('')}</svg><div class="chart-axis"><span>${weights[0].date.slice(5)}</span><strong>${weights.at(-1).value} kg</strong><span>${weights.at(-1).date.slice(5)}</span></div></div>`;
}
function historyView(recs){return `<section class="health-section"><div class="section-head"><h2>按时间排列</h2><button data-action="add-health">${icon('plus','sm')} 新增</button></div>${recs.length?`<div class="health-list">${recs.map(r=>healthRow(r)).join('')}</div>`:`<div class="health-empty">你的健康档案还没有记录。<br>无需每日打卡，重要时记一下就好。</div>`}<button class="health-add" data-action="add-health">${icon('plus','sm')} 写一条健康记录</button></section>`}
function healthRow(r,upcoming=false){const d=types[r.type]||types.note;return `<div class="health-row"><div class="health-icon">${icon(d[1],'sm')}</div><div class="health-row-content"><div class="health-row-title">${esc(r.title||(d[0]))}</div><div class="health-row-sub">${esc(r.type==='weight'?r.value+' kg':r.note||d[0])}</div></div><div class="health-row-time">${esc(upcoming?r.nextDate:r.date)}</div><button class="muted" data-action="delete-health" data-id="${esc(r.id)}" aria-label="删除记录">${icon('trash','sm')}</button></div>`}
function profileView(c){return `<section class="health-section"><div class="profile-photo-banner">${photoAvatar(c,'profile',true)}<div><strong>${hasRealPhoto(c)?'这张照片真可爱':'给小猫换上真实照片'}</strong><small>${hasRealPhoto(c)?'点击照片可以随时更换、重新裁剪':'从手机相册选一张，拖动并缩放裁剪'}</small></div><button data-action="upload-avatar" data-cat-id="${esc(c.id)}">${icon('camera','sm')} ${hasRealPhoto(c)?'更换':'上传'}</button></div><div class="section-head"><h2>关于这只小猫</h2><button data-action="edit-cat">${icon('edit','sm')} 编辑</button></div><div class="health-list"><div class="health-row"><div class="health-row-content"><div class="health-row-title">名字</div><div class="health-row-sub">${esc(c.name)}</div></div></div><div class="health-row"><div class="health-row-content"><div class="health-row-title">毛色与品种</div><div class="health-row-sub">${esc(c.breed||'待填写')}</div></div></div><div class="health-row"><div class="health-row-content"><div class="health-row-title">生日</div><div class="health-row-sub">${esc(c.birthday||'待填写')}</div></div></div><div class="health-row"><div class="health-row-content"><div class="health-row-title">到家日</div><div class="health-row-sub">${esc(c.arrival||'待填写')}</div></div></div><div class="health-row"><div class="health-row-content"><div class="health-row-title">性别 / 绝育</div><div class="health-row-sub">${esc(c.sex||'未知')} / ${esc(c.neutered||'未填写')}</div></div></div><div class="health-row"><div class="health-row-content"><div class="health-row-title">特别备注</div><div class="health-row-sub">${esc(c.note||'还没有特别备注')}</div></div></div></div><button class="health-add" data-action="edit-cat">${icon('edit','sm')} 修改猫咪资料</button></section>`}
function upcoming(catId){let r=state.health.filter(r=>r.catId===catId&&r.nextDate&&r.nextDate>=todayISO()).sort((a,b)=>a.nextDate.localeCompare(b.nextDate))[0];return r?`${r.nextDate.slice(5).replace('-','月')}日 · ${types[r.type]?.[0]||'提醒'}`:''}
const suggestions=['最近有健康记录吗？','帮我整理猫猫的动态','我记过体重吗？','疫苗驱虫需要提醒吗？'];
function chatView(){const c=cat();let items=state.chats.filter(x=>x.catId===c.id);
 return `<section class="v4-ai"><header class="v4-pagehead"><div><h1>懂喵君<span class="hand-heart">✧</span></h1><p>你的猫咪记录小助手 · 更懂你，也更懂它</p></div><button class="head-control" data-action="cats" aria-label="切换猫咪">${icon('paw')}</button></header>
 <div class="ai-story"><div class="ai-art"><img src="${D.nap}" alt="银灰色小猫手绘插画"/><span class="ai-bubble">嗷～<br>陪你慢慢记</span></div><p>有关于 <strong>${esc(c.name)}</strong> 的问题，<br>都可以来和我聊聊。</p><small>目前可查询本机动态与健康记录，尚未接入在线 AI。</small></div>
 <div class="ai-questions">${suggestions.map((q,i)=>`<button data-action="ask" data-question="${esc(q)}"><span class="ai-askicon">${icon(['heart','book','weight','calendar'][i])}</span><span>${esc(q)}</span>${icon('right','sm')}</button>`).join('')}</div>
 <div class="v4-chat-log" id="chatScroll" aria-live="polite">${items.map(m=>`<div class="message ${m.role==='user'?'me':'bot'}">${esc(m.text)}</div>`).join('')}</div>
 <form class="v4-ai-input" id="chatForm"><input name="question" maxlength="300" placeholder="和懂喵君聊一聊…" aria-label="向懂喵君提问" required/><button type="submit" aria-label="发送消息">${icon('send')}</button></form><p class="ai-disclaimer">本地记录检索体验版，不提供医疗诊断。</p>
 </section>`;
}
function assistantReply(q){const c=cat(),recs=state.health.filter(x=>x.catId===c.id),posts=state.posts.filter(x=>x.catId===c.id&&!x.demo),w=recs.filter(x=>x.type==='weight').sort((a,b)=>b.date.localeCompare(a.date)),up=recs.filter(x=>x.nextDate&&x.nextDate>=todayISO()).sort((a,b)=>a.nextDate.localeCompare(b.nextDate));if(/体重|多重|几斤/.test(q))return w.length?`我在${c.name}的健康小本本里找到了最近一次体重：${w[0].value} kg（${w[0].date}）。${w.length>1?`上一次是 ${w[1].value} kg，变化 ${(Number(w[0].value)-Number(w[1].value)).toFixed(2)} kg。`: '目前只有一条体重记录，暂时无法比较趋势。'}`:`还没有找到${c.name}的体重记录。可以在「健康小本本 → 体重」里新增一条，我下次就能帮你查到。`;if(/疫苗|驱虫|提醒|复诊/.test(q))return up.length?`我找到了 ${up.length} 条未到期提醒。最近一条是 ${up[0].nextDate}：${up[0].title||types[up[0].type][0]}。记得以兽医制定的时间表为准哦。`:`目前没有给${c.name}设置未来的疫苗、驱虫或复诊提醒。可以进入「健康小本本」添加；具体接种与驱虫频率请遵循兽医建议。`;if(/动态|朋友圈|记录|最近|总结/.test(q))return posts.length?`${c.name}有 ${posts.length} 条你亲自发布的动态。最近一条是 ${dateString(posts[0].createdAt)}：「${posts[0].text.slice(0,75)}」。\n\n我能帮你回顾记录，但还不能通过这些内容推断真实健康状态。`:`目前还没有你正式发布的猫咪动态（页面里的两条是体验示例）。点中间的「＋嗷呜」，留下一条今天的小事吧。`;if(/生病|吐|拉肚子|不吃|异常|精神不好|咳嗽|难受|猫癣/.test(q))return `我可以帮你整理${c.name}的异常观察和就诊记录，但无法判断疾病。建议及时记录症状出现的时间、频率，以及食欲、精神和排泄变化；如果症状严重或持续，请尽快联系兽医。`;return `收到啦～目前这是本地体验版，我能准确读取${c.name}已保存的动态和健康记录，但还不能像真正的 AI 医护顾问一样理解开放式问题。你可以试试问我“最近的体重是多少”或“有哪些待办提醒”。`}
function modal(html,title='',wide=true){ui.modal='custom';$$('overlay').innerHTML=`<div class="scrim" data-action="close"></div><div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-head"><h2 class="sheet-title">${esc(title)}</h2><button class="sheet-cancel" data-action="close">取消 ✕</button></div><div class="sheet-body">${html}</div></div>`}
function close(){ui.modal='';$$('overlay').innerHTML='';ui.draftPhotos=[];ui.draftText='';ui.draftTags=[]}
const tags=['好可爱','睡觉中','小猫营业','玩耍中','晒太阳','今天捣蛋','去医院了','有点异常'];
function compose(){ui.draftPhotos=[];ui.draftTags=[];ui.draftText='';showComposer()}
function showComposer(){modal(`<form id="composeForm"><label class="form-label">分享一只小猫的生活</label><select class="form-control" name="catId">${state.cats.map(c=>`<option ${c.id===state.selected?'selected':''} value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select><label class="form-label">今天想说点什么？</label><textarea class="form-control form-textarea" name="text" placeholder="比如：今天的猫咪又发现一只新纸箱……" maxlength="1000">${esc(ui.draftText)}</textarea><label class="form-label">加几张照片吧（最多 4 张）</label><div class="draft-image-row" id="draftImages">${draftPhotoHTML()}</div><input id="postFiles" class="hidden" type="file" accept="image/*" multiple/><label class="form-label">一些小标签（可选）</label><div class="tag-picker" id="tagPicker">${tagPickerHTML()}</div><button class="primary-button" type="submit">发布嗷呜 ✳</button><p class="form-hint" style="margin-top:12px">发布后的内容仅保存在当前设备上，不会公开到互联网。</p></form>`,'嗷呜一下')}
function draftPhotoHTML(){return `${ui.draftPhotos.map((p,i)=>`<div class="draft-thumbnail"><img src="${p}" alt="准备发布的照片"/><button type="button" data-action="remove-draft" data-index="${i}">✕</button></div>`).join('')}${ui.draftPhotos.length<4?`<button class="upload-box" type="button" data-action="upload-post">${icon('plus')}</button>`:''}`}
function tagPickerHTML(){return tags.map(t=>`<button class="tag-option ${ui.draftTags.includes(t)?'selected':''}" type="button" data-action="toggle-tag" data-tag="${esc(t)}">${esc(t)}</button>`).join('')}
function recordModal(type=ui.activeRecordType){ui.activeRecordType=type;const d=types[type];modal(`<form id="recordForm"><input type="hidden" name="type" value="${type}"/><label class="form-label">记录日期</label><input class="form-control" type="date" name="date" required value="${todayISO()}"/>${type==='weight'?`<label class="form-label">体重 / kg</label><input class="form-control" name="value" type="number" min="0.1" max="40" step="0.01" placeholder="例如 3.25" required />`:`<label class="form-label">${type==='vaccine'?'疫苗名称':type==='deworm'?'驱虫名称':type==='visit'?'就诊医院 / 原因':'观察主题'}</label><input class="form-control" name="title" maxlength="70" placeholder="写下一件需要记住的事" required/>`}<label class="form-label">补充说明（可选）</label><textarea class="form-control form-textarea" name="note" maxlength="500" placeholder="具体情况、医生建议、发现的小变化……"></textarea>${['vaccine','deworm','visit'].includes(type)?`<label class="form-label">下次提醒（可选）</label><input class="form-control" name="nextDate" type="date"/><p class="form-hint">日期请根据兽医建议填写，App 不会自动推断接种周期。</p>`:''}<button class="primary-button" type="submit">保存到健康小本本</button></form>`,d[0])}
function catsModal(){modal(`<div class="cat-list">${state.cats.map(c=>`<button class="cat-option ${c.id===state.selected?'selected':''}" data-action="choose-cat" data-id="${esc(c.id)}">${photoAvatar(c,'medium',false)}<div><strong>${esc(c.name)}</strong><p>${esc(c.breed||'刚搬来的小猫')}</p></div><span class="circle-action">${c.id===state.selected?icon('check'):icon('right')}</span></button>`).join('')}</div><button class="health-add" style="margin:17px 0" data-action="add-cat">${icon('plus','sm')} 接一只新小猫回家</button><p class="form-hint">每只小猫都有独立的动态、健康档案和聊天记录。</p>`,'猫猫家庭')}
function catForm(edit=false){ui.catFormMode=edit?'edit':'add';const c=edit?cat():{name:'',breed:'',birthday:'',arrival:'',sex:'',neutered:'',note:''};modal(`<form id="catForm"><label class="form-label">小猫的名字</label><input class="form-control" required maxlength="18" name="name" placeholder="给猫咪起个名字" value="${esc(c.name)}"/><label class="form-label">毛色 / 品种（可选）</label><input class="form-control" maxlength="60" name="breed" placeholder="例如：银灰色长毛虎斑" value="${esc(c.breed||'')}"/><div class="form-row"><div><label class="form-label">生日（可选）</label><input type="date" class="form-control" name="birthday" value="${esc(c.birthday||'')}"/></div><div><label class="form-label">到家日（可选）</label><input type="date" class="form-control" name="arrival" value="${esc(c.arrival||'')}"/></div></div><div class="form-row"><div><label class="form-label">性别</label><select class="form-control" name="sex"><option value="">暂不填写</option>${['小公主','小王子','未知'].map(s=>`<option ${s===c.sex?'selected':''}>${s}</option>`).join('')}</select></div><div><label class="form-label">绝育情况</label><select class="form-control" name="neutered"><option value="">暂不填写</option>${['已绝育','未绝育','未知'].map(s=>`<option ${s===c.neutered?'selected':''}>${s}</option>`).join('')}</select></div></div><label class="form-label">特别备注</label><textarea class="form-control form-textarea" name="note" maxlength="300" placeholder="小猫的小习惯、过敏、特别注意事项……">${esc(c.note||'')}</textarea><label class="form-label">猫咪真实照片（可选）</label><label class="form-photo-picker">${photoAvatar({...c,id:edit?c.id:'new',photo:edit?c.photo:''},'form',false)}<span><strong>从相册上传照片</strong><small>可拖动、缩放和裁剪头像</small></span><input type="file" accept="image/*" id="catPhotoFile" class="hidden"/></label><p id="catPhotoHint" class="form-hint">${edit?'不选则保留已经上传的照片':'可以稍后再添加'}</p><button class="primary-button" type="submit">${edit?'保存资料':'欢迎新小猫回家'}</button></form>`,edit?'编辑猫咪资料':'新成员入住')}
function settings(){modal(`<div class="eyebrow">CAT LIVES MATTER ♡</div><p class="page-subtitle" style="margin:7px 0 15px">猫在呢 · Awoo Here<br>当前为可离线使用的手机端 MVP。</p><button class="setting-row" data-action="cats">${icon('paw')}<span>猫猫家庭</span>${icon('right','sm')}</button><button class="setting-row" data-action="edit-cat">${icon('edit')}<span>修改当前猫咪资料</span>${icon('right','sm')}</button><button class="setting-row" data-action="backup">${icon('download')}<span>导出本机数据备份</span>${icon('right','sm')}</button><label class="setting-row" style="cursor:pointer">${icon('refresh')}<span>从备份导入数据</span><input id="importFile" style="display:none" type="file" accept="application/json,.json"/>${icon('right','sm')}</label><div class="settings-divider"></div><p class="tiny-note">隐私说明：当前版本没有账户和云端同步。动态、档案与聊天内容保存在此设备浏览器中；清理网站数据可能导致丢失，建议定期导出备份。<br><br>「懂喵君」目前只提供本地记录检索，不是真正的 AI 模型。真实多设备同步、在线 AI 和 App Store 上架属于后续开发阶段。</p>`,'设置与备份')}

// The portrait picker is intentionally camera-first, never preloads a cartoon cat.
let avatarUploadTarget=null;
let avatarCropSession=null;
async function startAvatarCrop(file,catId,mode='immediate'){
 if(!file.type.startsWith('image/'))throw Error('请选择猫咪照片');
 if(file.size>16*1024*1024)throw Error('请选择小于 16MB 的照片');
 const url=URL.createObjectURL(file);
 let image;
 try{image=await new Promise((resolve,reject)=>{const pic=new Image();pic.onload=()=>resolve(pic);pic.onerror=()=>reject(Error('暂时无法读取这张照片，请换一张 JPEG 或 PNG'));pic.src=url;});}
 catch(err){URL.revokeObjectURL(url);throw err;}
 const canvas=document.createElement('canvas');canvas.width=640;canvas.height=640;
 const overlay=document.createElement('div');overlay.className='avatar-crop-overlay';overlay.id='avatarCropOverlay';overlay.innerHTML=`<div class="avatar-crop-shade"></div><section class="avatar-crop-sheet" role="dialog" aria-modal="true" aria-label="裁剪猫咪头像"><div class="avatar-crop-top"><div><p>CAT PORTRAIT</p><h2>选一张它最可爱的照片</h2></div><button type="button" data-crop="cancel" aria-label="关闭头像编辑">${icon('close','sm')}</button></div><p class="avatar-crop-intro">拖动照片调整位置，拉动滑块放大，让猫咪的脸留在圆圈里。</p><div class="avatar-crop-canvas"><div class="avatar-crop-circle"></div><div id="cropCanvasHolder"></div></div><label class="avatar-zoom-label">${icon('image','sm')}<span>调整大小</span><input id="avatarZoom" type="range" min="1" max="2.6" value="1" step="0.01" aria-label="调整头像缩放大小"/></label><div class="avatar-crop-actions"><button type="button" class="crop-secondary" data-crop="cancel">取消</button><button type="button" class="crop-primary" data-crop="save">使用这张照片</button></div><p class="avatar-crop-privacy">照片仅保存在这台设备的浏览器里，不会自动上传到公开网站或 GitHub。</p></section>`;
 document.body.appendChild(overlay);
 overlay.querySelector('#cropCanvasHolder').appendChild(canvas);
 const s={overlay,canvas,image,url,catId,mode,zoom:1,panX:0,panY:0,down:false,lastX:0,lastY:0};avatarCropSession=s;
 const clamp=(v,lo,hi)=>Math.min(hi,Math.max(lo,v));
 function paint(){
  let scale=Math.max(640/image.naturalWidth,640/image.naturalHeight)*s.zoom;
  let w=image.naturalWidth*scale,h=image.naturalHeight*scale;
  let mx=Math.max(0,(w-640)/2),my=Math.max(0,(h-640)/2);
  s.panX=clamp(s.panX,-mx,mx);s.panY=clamp(s.panY,-my,my);
  const ctx=canvas.getContext('2d');ctx.clearRect(0,0,640,640);
  ctx.fillStyle='#f5f3ed';ctx.fillRect(0,0,640,640);
  ctx.drawImage(image,(640-w)/2+s.panX,(640-h)/2+s.panY,w,h);
 }
 s.paint=paint;paint();
 canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;s.down=true;s.lastX=e.clientX;s.lastY=e.clientY;canvas.setPointerCapture(e.pointerId);});
 canvas.addEventListener('pointermove',e=>{if(!s.down)return;const f=640/Math.max(1,canvas.getBoundingClientRect().width);s.panX+=(e.clientX-s.lastX)*f;s.panY+=(e.clientY-s.lastY)*f;s.lastX=e.clientX;s.lastY=e.clientY;paint();});
 canvas.addEventListener('pointerup',()=>{s.down=false;});canvas.addEventListener('pointercancel',()=>{s.down=false;});
 overlay.querySelector('#avatarZoom').addEventListener('input',e=>{s.zoom=Number(e.target.value);paint();});
 overlay.addEventListener('click',e=>{const action=e.target.closest('[data-crop]')?.dataset.crop;
  if(action==='cancel')endAvatarCrop();
  if(action==='save'){
   paint();const output=document.createElement('canvas');output.width=512;output.height=512;
   output.getContext('2d').drawImage(canvas,0,0,512,512);
   const photo=output.toDataURL('image/jpeg',.84);
   if(s.mode==='form'){
    pendingCatPhoto=photo;
    const picker=document.querySelector('#catForm .form-photo-picker .pet-photo-avatar');
    if(picker){picker.classList.remove('needs-photo');picker.classList.add('has-photo');picker.innerHTML=`<img src="${photo}" alt="新选的猫咪真实照片"/>`;}
    const hint=$$('catPhotoHint');if(hint)hint.textContent='已经裁剪好啦，保存资料后生效';
    endAvatarCrop();toast('照片已裁剪，别忘了保存猫咪资料');
   }else{
    const target=state.cats.find(c=>c.id===s.catId);
    if(!target){endAvatarCrop();toast('没有找到对应的猫咪');return;}
    const old=target.photo;target.photo=photo;
    if(!persist()){target.photo=old;endAvatarCrop();return;}
    endAvatarCrop();render();toast('真实猫咪头像已经保存 ♡');
   }
  }
 });
}
function endAvatarCrop(){const s=avatarCropSession;if(!s)return;avatarCropSession=null;s.overlay.remove();URL.revokeObjectURL(s.url);}

let pendingCatPhoto=null;
async function compress(file,max=1000,q=.75){if(!file.type.startsWith('image/'))throw Error('请选择图片文件');if(file.size>14*1024*1024)throw Error('单张图片不能超过 14MB');const data=await new Promise((resolve,reject)=>{let rd=new FileReader();rd.onload=()=>resolve(rd.result);rd.onerror=()=>reject(Error('照片读取失败'));rd.readAsDataURL(file)});const im=await new Promise((res,rej)=>{const img=new Image();img.onload=()=>res(img);img.onerror=()=>rej(Error('无法加载这张照片'));img.src=data});const ratio=Math.min(1,max/Math.max(im.naturalWidth,im.naturalHeight));let canv=document.createElement('canvas');canv.width=Math.round(im.naturalWidth*ratio);canv.height=Math.round(im.naturalHeight*ratio);const ctx=canv.getContext('2d');ctx.drawImage(im,0,0,canv.width,canv.height);return canv.toDataURL('image/jpeg',q)}
let toastTimer;function toast(msg){const x=$$('toast');x.textContent=msg;x.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>x.classList.remove('show'),3100)}
function ask(q){const c=cat();state.chats.push({id:uid('chat'),catId:c.id,role:'user',text:q,date:new Date().toISOString()});state.chats.push({id:uid('chat'),catId:c.id,role:'assistant',text:assistantReply(q),date:new Date().toISOString()});persist();render();setTimeout(()=>{let sc=$$('chatScroll');if(sc)sc.scrollTop=sc.scrollHeight},0)}
function changeTab(t){ui.tab=t;close();render(true)}
function exportBackup(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Awoo-Here-猫在呢-备份-'+todayISO()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('备份已导出，请妥善保存')}
function deletePost(id){const p=state.posts.find(p=>p.id===id);if(!p)return;if(!confirm('确定删除这条嗷呜吗？删除后无法恢复。'))return;state.posts=state.posts.filter(x=>x.id!==id);persist();render();toast('这条动态已删除')}
function deleteHealth(id){if(!confirm('确定删除这条健康记录？'))return;state.health=state.health.filter(x=>x.id!==id);persist();render();toast('记录已删除')}

// Autonomous pixel-cat room: no fake tap interactions or "care" obligations.
const roomBehavior={timer:null,frame:null,token:0,x:.46,index:0,walkFrameTimer:null};
const roomSequence=[
 {pose:'sit',duration:1300,caption:'晒晒太阳'},
 {pose:'walk',duration:3900,target:.76,caption:'巡视自己的地盘'},
 {pose:'sit',duration:1200,caption:'发现了一个好位置'},
 {pose:'stretch',duration:2700,caption:'伸一个大大的懒腰'},
 {pose:'walk',duration:4800,target:.25,caption:'再四处走一走'},
 {pose:'loaf',duration:3300,caption:'把小手手收起来'},
 {pose:'sleep',duration:5200,caption:'安安心心睡一会儿'},
 {pose:'sit',duration:1800,caption:'醒啦，看看窗外'},
 {pose:'walk',duration:3700,target:.63,caption:'慢慢地散个步'},
 {pose:'stretch',duration:2400,caption:'伸伸腰，活动一下'},
 {pose:'sleep',duration:4300,caption:'继续做个好梦'}
];
function stopRoomLife(){roomBehavior.token++;clearTimeout(roomBehavior.timer);clearInterval(roomBehavior.walkFrameTimer);cancelAnimationFrame(roomBehavior.frame);roomBehavior.timer=null;roomBehavior.walkFrameTimer=null;}
function startRoomLife(){
 const actor=$$('roomCatActor'),img=$$('roomCat'),status=$$('roomMotion');if(!actor||!img||ui.tab!=='home')return;
 const token=roomBehavior.token;
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const room=$$('homeRoom');let previousX=Math.min(.75,Math.max(.25,roomBehavior.x));
 function run(){
  if(token!==roomBehavior.token||ui.tab!=='home'||document.hidden||!actor.isConnected)return;
  const move=roomSequence[roomBehavior.index++ % roomSequence.length];
  clearInterval(roomBehavior.walkFrameTimer);roomBehavior.walkFrameTimer=null;
  img.classList.remove('is-walking','is-stretching','is-breathing');
  status.textContent=move.caption;
  actor.style.transition='none'; actor.style.left=(previousX*100)+'%';
  if(move.pose==='walk'){
   const next=move.target??(previousX>.5?.25:.72);
   actor.style.setProperty('--face',next<previousX?1:-1);
   img.src=sprite('walk');img.classList.add('is-walking');
   let frame=0;roomBehavior.walkFrameTimer=setInterval(()=>{if(token!==roomBehavior.token||!img.isConnected){clearInterval(roomBehavior.walkFrameTimer);return;}img.src=sprite(['walk','walk-step1','walk','walk-step2'][frame++%4]);},205);
   roomBehavior.frame=requestAnimationFrame(()=>{roomBehavior.frame=requestAnimationFrame(()=>{if(token!==roomBehavior.token)return;actor.style.transition=`left ${move.duration}ms linear`;actor.style.left=(next*100)+'%';});});
   previousX=next;roomBehavior.x=next;
  }else{
   img.src=sprite(move.pose);img.classList.add(move.pose==='stretch'?'is-stretching':'is-breathing');
  }
  roomBehavior.timer=setTimeout(run,move.duration);
 }
 actor.style.transition='none';actor.style.left=(previousX*100)+'%';
 if(reduce){img.src=sprite('loaf');status.textContent='在这里安心地待着';return;}
 // Start the first visible action promptly, without interaction. Following phases continue indefinitely.
 run();
}
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopRoomLife();}else if(ui.tab==='home'&&!roomBehavior.timer){startRoomLife();}});

// delegated actions
function actions(e){const el=e.target.closest('[data-action],[data-tab],[data-filter],[data-healthtab]');if(!el)return;if(el.dataset.tab){changeTab(el.dataset.tab);return}if(el.dataset.filter){ui.feedFilter=el.dataset.filter;render();return}if(el.dataset.healthtab){ui.healthTab=el.dataset.healthtab;render();return}let ac=el.dataset.action;switch(ac){case 'settings':settings();break;case 'cats':catsModal();break;case 'compose':compose();break;case 'close':close();break;case 'record-type':recordModal(el.dataset.type);break;case 'add-health':recordModal('weight');break;case 'choose-cat':state.selected=el.dataset.id;persist();close();render(true);break;case 'add-cat':pendingCatPhoto=null;catForm(false);break;case 'edit-cat':pendingCatPhoto=null;catForm(true);break;case 'upload-avatar':avatarUploadTarget=el.dataset.catId||state.selected;$$('avatarQuickFile')?.click();break;case 'like':{const p=state.posts.find(x=>x.id===el.dataset.id);if(p){p.liked=!p.liked;persist();render()}break}case 'delete-post':deletePost(el.dataset.id);break;case 'delete-health':deleteHealth(el.dataset.id);break;case 'ask':ask(el.dataset.question);break;case 'upload-post':$$('postFiles')?.click();break;case 'remove-draft':{const ta=document.querySelector('#composeForm textarea[name=text]');if(ta)ui.draftText=ta.value;ui.draftPhotos.splice(Number(el.dataset.index),1);$$('draftImages').innerHTML=draftPhotoHTML();break}case 'toggle-tag':{const ta=document.querySelector('#composeForm textarea[name=text]');if(ta)ui.draftText=ta.value;const t=el.dataset.tag;ui.draftTags=ui.draftTags.includes(t)?ui.draftTags.filter(x=>x!==t):[...ui.draftTags,t];$$('tagPicker').innerHTML=tagPickerHTML();break}case 'backup':exportBackup();break;}}
async function inputs(e){const el=e.target;if(el.id==='postFiles'){const files=[...(el.files||[])].slice(0,4-ui.draftPhotos.length);try{for(const f of files){const base=await compress(f,950,.68);ui.draftPhotos.push(base)}$$('draftImages').innerHTML=draftPhotoHTML();toast('照片已添加')}catch(err){toast(err.message)}el.value=''}if(el.id==='avatarQuickFile'&&el.files[0]){try{await startAvatarCrop(el.files[0],avatarUploadTarget,'immediate')}catch(err){toast(err.message)}el.value=''}
if(el.id==='catPhotoFile'&&el.files[0]){try{await startAvatarCrop(el.files[0],state.selected,'form')}catch(err){toast(err.message)}el.value=''}if(el.id==='importFile'&&el.files[0]){try{const text=await el.files[0].text();const obj=JSON.parse(text);if(!obj.cats?.length||!Array.isArray(obj.posts)||!Array.isArray(obj.health))throw Error('备份文件格式不正确');if(!confirm('导入备份会覆盖当前设备上的全部记录。确定继续吗？'))return;state={version:1,cats:obj.cats,selected:obj.selected,posts:obj.posts,health:obj.health,chats:obj.chats||[]};persist();close();render(true);toast('备份导入成功')}catch(err){toast(err.message)}}}
function onSubmit(e){if(e.target.id==='chatForm'){e.preventDefault();const input=e.target.elements.question;const q=input.value.trim();if(q)ask(q);return}if(e.target.id==='composeForm'){e.preventDefault();const fd=new FormData(e.target);const text=String(fd.get('text')||'').trim();if(!text&&!ui.draftPhotos.length){toast('写一句话，或者选择一张猫咪照片吧');return}const post={id:uid('post'),catId:String(fd.get('catId')||state.selected),text,photos:[...ui.draftPhotos],tags:[...ui.draftTags],createdAt:new Date().toISOString(),demo:false,liked:false};state.posts.unshift(post);if(!persist()){state.posts.shift();return}ui.feedFilter='all';close();ui.tab='feed';render(true);toast('嗷呜成功！今天也有新的小故事 ✳');return}if(e.target.id==='recordForm'){e.preventDefault();const fd=new FormData(e.target),type=String(fd.get('type')),val=String(fd.get('value')||'');if(type==='weight'&&(!val||Number(val)<=0)){toast('请输入有效体重');return}state.health.push({id:uid('health'),catId:state.selected,type,date:String(fd.get('date')),title:String(fd.get('title')||''),value:val,note:String(fd.get('note')||''),nextDate:String(fd.get('nextDate')||'')});persist();close();ui.tab='health';ui.healthTab='overview';render();toast('健康记录保存好啦');return}if(e.target.id==='catForm'){e.preventDefault();const fd=new FormData(e.target),vals={name:String(fd.get('name')||'').trim(),breed:String(fd.get('breed')||'').trim(),birthday:String(fd.get('birthday')||''),arrival:String(fd.get('arrival')||''),sex:String(fd.get('sex')||''),neutered:String(fd.get('neutered')||''),note:String(fd.get('note')||'')};if(!vals.name){toast('给小猫取一个名字吧');return}if(ui.catFormMode==='edit'){Object.assign(cat(),vals);if(pendingCatPhoto)cat().photo=pendingCatPhoto}else{const id=uid('cat');state.cats.push({...vals,id,photo:pendingCatPhoto||'',createdAt:new Date().toISOString()});state.selected=id}persist();pendingCatPhoto=null;close();render(true);toast('猫咪资料保存成功 ♡');return}}
$$('app').addEventListener('click',actions);$$('tabbar').addEventListener('click',actions);$$('overlay').addEventListener('click',actions);$$('overlay').addEventListener('change',inputs);$$('avatarQuickFile').addEventListener('change',inputs);document.addEventListener('submit',onSubmit);render(true);
if('serviceWorker' in navigator) navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>r.unregister())).catch(()=>{});
})();

